VALUES
  ($emailextract$INVITATION$emailextract$,
   $emailextract$Account invitation$emailextract$,
   $emailextract$The activation link that turns an invited contact into an account holder. One template, two voices: the first send welcomes, the resend says "this is the same link you already have" so a mailbox can be triaged on the subject line.$emailextract$,
   $emailextract$INVITATION$emailextract$,
   $emailextract${{#if MSG.IS_RESEND}}Here's your invitation link again — {{ORG.BRAND_NAME}}{{else}}Your invitation to {{ORG.BRAND_NAME}}{{/if}}$emailextract$,
   $emailextract$
      {{#if MSG.IS_RESEND}}<p>Here's that link again — this is the <strong>same invitation</strong> we sent you
       before, not a new one. If you still have the first email, either link works.</p>{{else}}<p>Welcome — we're so glad to have you.</p>{{/if}}
      {{#if MSG.OFFERING_LABEL}}<p>Your {{MSG.OFFERING_LABEL}} is ready — create your account to sign your documents and get started.</p>{{/if}}
      {{#if MSG.CHECKLIST}}<p>When you click the link, here's what we'll ask you to do:</p><ul style="padding-left:18px">{{#each MSG.CHECKLIST}}<li style="margin:4px 0"><strong>{{.TITLE}}</strong> — {{.ACTION}}</li>{{/each}}</ul><p style="color:#666;font-size:13px">This same checklist will be on your dashboard, ticking itself off as you go.</p>{{/if}}
      <p>Create your account here to join the community. You can sign up with Google
      or set a password — your choice on the next page:</p>
      <p><a href="{{MSG.LINK}}">{{MSG.LINK}}</a></p>
      <p>{{#if MSG.EXPIRES_ON}}This link is valid until <strong>{{MSG.EXPIRES_ON}}</strong>. If it expires, just reach out and we'll send a fresh one.{{else}}This link expires soon. If it does, just reach out and we'll send a fresh one.{{/if}}</p>
      <hr/><pre style="font-family:inherit">{{ORG.FOOTER}}</pre>$emailextract$,
   $emailextract$invite$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$The invited address on the invitation row. Staff-initiated (admin-send-invitation), staff resend (admin-resend-invitation) and the invitee's own "send it again" (invitation-resend-request) all reach this one template.$emailextract$,
   true),

  ($emailextract$CONTRACT_INVITE$emailextract$,
   $emailextract$Contract ready to sign$emailextract$,
   $emailextract$Sent to a contract counterparty when a document is prepared for them. The list of what they will be asked to do is built from that party's own document controls, so the email never promises an action the controls do not allow.$emailextract$,
   $emailextract$CONTRACT$emailextract$,
   $emailextract$A contract is ready for you — {{ORG.BRAND_NAME}}$emailextract$,
   $emailextract$<p>Hello,</p><p><strong>{{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}A contract{{/if}}</strong> has been prepared for you.</p><p><a href="{{MSG.LINK}}">Open the contract</a> — sign in with Google if this is a Gmail address, or set a password with this email. You'll land directly on the contract to {{#if DOC.PARTY_NEEDS_INFO}}add your information, {{/if}}{{#if DOC.PARTY_CAN_EDIT_DEAL}}review and edit the terms{{else}}{{#if DOC.PARTY_CAN_SUGGEST}}review and suggest changes{{else}}review the terms{{/if}}{{/if}}, and sign.</p><p style="color:#666;font-size:12px">This link is personal to {{MSG.RECIPIENT_EMAIL}} and expires in 14 days.<br/>{{MSG.LINK}}</p>{{#if ORG.FOOTER}}<hr/><p style="color:#666;font-size:12px;white-space:pre-line">{{ORG.FOOTER}}</p>{{/if}}$emailextract$,
   $emailextract$tenant$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$The counterparty contact on the named party role, at the address on their contact record (or one passed by staff). Never sent to someone who has already signed.$emailextract$,
   true),

  ($emailextract$CONTRACT_VOIDED$emailextract$,
   $emailextract$Contract voided by the other party$emailextract$,
   $emailextract$The email half of a void. The in-app notification is written by the database; this carries the same note plus the keep-or-remove choice, and says plainly that removing it only affects the reader's own documents page.$emailextract$,
   $emailextract$CONTRACT$emailextract$,
   $emailextract${{#if PARTY.FULL_NAME}}{{PARTY.FULL_NAME}}{{else}}The other party{{/if}} voided {{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}your contract{{/if}}$emailextract$,
   $emailextract$<p>Hello,</p><p><strong>{{#if PARTY.FULL_NAME_HTML}}{{PARTY.FULL_NAME_HTML}}{{else}}The other party{{/if}}</strong> voided <strong>{{#if DOC.HAS_TITLE}}{{DOC.TITLE_HTML}}{{else}}your contract{{/if}}</strong>. It is no longer going ahead.</p>{{#if MSG.NOTE_HTML}}<p>They left this note:</p><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #ddd;color:#444">{{MSG.NOTE_HTML}}</blockquote>{{else}}<p>No reason was given.</p>{{/if}}<p><a href="{{MSG.LINK}}">Open the contract</a> to keep a copy on your documents page, or remove it from your view.</p><p style="color:#666;font-size:12px">Removing it only affects your own documents page — the record is retained.<br/>{{MSG.LINK}}</p>{{#if ORG.FOOTER}}<hr/><p style="color:#666;font-size:12px;white-space:pre-line">{{ORG.FOOTER}}</p>{{/if}}$emailextract$,
   $emailextract$tenant$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$Every other party on the document who has an email address on file.$emailextract$,
   true),

  ($emailextract$CONTRACT_CHANGE_REQUESTS$emailextract$,
   $emailextract$Change requests submitted for review$emailextract$,
   $emailextract$Lists the five highest-impact change requests a party submitted. The ranking is the database's (change_request_impact_rank) — money, then liability, then term, and so on — so the email and the app agree on what matters most.$emailextract$,
   $emailextract$CONTRACT$emailextract$,
   $emailextract${{#if PARTY.FULL_NAME}}{{PARTY.FULL_NAME}}{{else}}The other party{{/if}} requested changes to {{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}your contract{{/if}}$emailextract$,
   $emailextract$<p>Hello,</p><p><strong>{{#if PARTY.FULL_NAME_HTML}}{{PARTY.FULL_NAME_HTML}}{{else}}The other party{{/if}}</strong> submitted change requests on <strong>{{#if DOC.HAS_TITLE}}{{DOC.TITLE_HTML}}{{else}}your contract{{/if}}</strong> for your review.</p><p>The most significant {{#if MSG.IS_SINGLE}}one is{{else}}{{MSG.COUNT}} are{{/if}}:</p><ol>{{#each MSG.ITEMS}}<li style="margin-bottom:8px"><strong>#{{.NUMBER}} — {{#if .HAS_SECTION}}{{.WHERE_HTML}}{{else}}The whole document{{/if}}</strong><br/>{{.BODY_HTML}}</li>{{/each}}</ol><p><a href="{{MSG.LINK}}">Open the contract</a> to reply to each request and agree or discuss.</p><p style="color:#666;font-size:12px">The contract cannot be locked for signing until these are resolved.<br/>{{MSG.LINK}}</p>{{#if ORG.FOOTER}}<hr/><p style="color:#666;font-size:12px;white-space:pre-line">{{ORG.FOOTER}}</p>{{/if}}$emailextract$,
   $emailextract$tenant$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$Every other party on the document who has an email address on file.$emailextract$,
   true),

  ($emailextract$CONTRACT_WORKING_COPY$emailextract$,
   $emailextract$Working copy of a contract$emailextract$,
   $emailextract$A party asks for the contract as it stands right now, unexecuted, so an adviser can read it. Unselected options and empty fields are included on purpose and the email says so, because a working copy that looked finished would be worse than none.$emailextract$,
   $emailextract$CONTRACT$emailextract$,
   $emailextract$Working copy — {{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}Contract{{/if}}$emailextract$,
   $emailextract$<p>Attached is the current working copy of <strong>{{#if DOC.HAS_TITLE}}{{DOC.TITLE}}{{else}}this contract{{/if}}</strong>{{#if DOC.DISPLAY_CODE}} ({{DOC.DISPLAY_CODE}}){{/if}}.</p><p>It is <strong>not executed</strong> and reflects the contract as of {{MSG.GENERATED_AT}}. Unselected options and empty fields are included on purpose, so anyone advising you can see what is still open.</p>$emailextract$,
   $emailextract$tenant$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$The requesting party, at their contact address (falling back to their account's).$emailextract$,
   true),

  ($emailextract$DOCUMENT_PARTY_COPY$emailextract$,
   $emailextract$Your signed document (single)$emailextract$,
   $emailextract$A signer's own copy of one executed document, with the PDF attached. Deliberately plain — no personalised greeting, matching the company copy's tone. Only the PDF filename is personalised. Carries a short reference code, never the full integrity hash.$emailextract$,
   $emailextract$DOCUMENT$emailextract$,
   $emailextract${{DOC.TITLE}} — signed and executed$emailextract$,
   $emailextract${{#if MSG.IS_GUARDIAN_COPY}}<p>Hi {{#if PARTY.GUARDIAN_FIRST_NAME}}{{PARTY.GUARDIAN_FIRST_NAME}}{{else}}there{{/if}},</p><p>The document <strong>{{DOC.TITLE}}</strong> for {{#if PARTY.FULL_NAME}}{{PARTY.FULL_NAME}}{{else}}the minor named on this document{{/if}} has been signed and executed. The PDF is attached.</p>{{else}}<p>Your document <strong>{{DOC.TITLE}}</strong> has been signed and executed. The PDF is attached.</p>{{/if}}<p style="font-size:16px;margin-top:16px"><strong>{{ORG.BRAND_NAME}}</strong>{{#if ORG.PHONE}}<br/><a href="tel:{{ORG.PHONE_TEL}}" style="color:inherit;text-decoration:none">{{ORG.PHONE}}</a>{{/if}}{{#if ORG.SITE_LINK}}<br/><a href="https://{{ORG.SITE_HOST}}" style="color:inherit">{{ORG.SITE_LINK}}</a>{{/if}}</p>{{#if DOC.REFERENCE_CODE}}<p style="color:#888;font-size:12px">Reference code: {{DOC.REFERENCE_CODE}}</p>{{/if}}$emailextract$,
   $emailextract$tenant$emailextract$,
   $emailextract$none$emailextract$,
   $emailextract$Each party on the executed document, once per document (a unique index makes a duplicate impossible). A minor's copy is addressed to their guardian; with no guardian email the send is skipped and staff are alerted.$emailextract$,
   true),

