   $emailextract$<p>{{#if PARTY.GREETING_NAME}}Hi {{PARTY.GREETING_NAME}},{{else}}Hello,{{/if}}</p>{{#if MSG.IS_GUARDIAN_COPY}}<p>A horse evaluation report{{#if HORSE.LABEL}} for {{HORSE.LABEL}}{{/if}} has been prepared for {{#if PARTY.FULL_NAME}}{{PARTY.FULL_NAME}}{{else}}the account holder{{/if}} and is attached to this email.</p>{{else}}{{#if MSG.IS_SHARE}}<p>A horse evaluation report has been shared with you{{#if HORSE.LABEL}} for {{HORSE.LABEL}}{{/if}}. It's attached to this email.</p>{{else}}<p>Your horse evaluation report{{#if HORSE.LABEL}} for {{HORSE.LABEL}}{{/if}} is attached to this email.</p>{{/if}}{{/if}}<p>Please keep it for your records.</p>{{#if ORG.FOOTER}}<hr/><p style="color:#666;font-size:12px;white-space:pre-line">{{ORG.FOOTER}}</p>{{/if}}$emailextract$,
   $emailextract$tenant$emailextract$,
